+    metrics.insert("masquerade".to_string(), count(|p| p.masquerade));
+    metrics.insert("missing".to_string(), missing as f64);
+    metrics.insert("process_count".to_string(), observed.len() as f64);
+    Ok(Classification {
+        metrics,
+        pending,
+        learned,
+        seen,
+    })
